    adcs_quat_t q_a, q_b, q_a_conj, q_rel;
    double abs_w, clamped_w, dist;

    if ((a == NULL) || (b == NULL) || (distance_rad == NULL)) {
        return ADCS_E_NULL;
    }

    if (adcs_quat_normalize(a, &q_a) != ADCS_OK) {
        return ADCS_E_DEGENERATE;
    }

    if (adcs_quat_normalize(b, &q_b) != ADCS_OK) {
        return ADCS_E_DEGENERATE;
    }

    q_a_conj = adcs_quat_conjugate(&q_a);
    q_rel = adcs_quat_multiply(&q_b, &q_a_conj);

    abs_w = fabs(q_rel.w);
    clamped_w = ADCS_CLAMP(abs_w, 0.0, 1.0);
    dist = 2.0 * acos(clamped_w);

    if (!isfinite(dist)) {
        return ADCS_E_NOT_FINITE;
    }

    *distance_rad = dist;
    return ADCS_OK;
}

